import React, { useState } from 'react';

const LOGO = "data:image/png;base64,";
const HERO_BG = "data:image/png;base64,";

function FrontPage({ onGetStarted, onLogin }) {
  return (
    <div style={{ minHeight:'100vh', background:'#000000', color:'white', overflow:'hidden', position:'relative' }}>
      {/* HERO BACKGROUND IMAGE - Your uploaded LS frontpage hero */}
      <div style={{
        position:'fixed',
        inset:0,
        backgroundImage:`url(${HERO_BG})`,
        backgroundRepeat:'no-repeat',
        backgroundPosition:'center',
        backgroundSize:'cover',
        zIndex:0
      }} />
      
      {/* Dark overlay for text readability */}
      <div style={{
        position:'fixed',
        inset:0,
        background:'linear-gradient(to bottom, rgba(0,0,0,0.3) 0%, rgba(0,0,0,0.6) 60%, rgba(0,0,0,0.9) 100%)',
        zIndex:1,
        pointerEvents:'none'
      }} />

      <nav style={{ position:'fixed', top:0, width:'100%', zIndex:50, background:'rgba(0,0,0,0.6)', backdropFilter:'blur(12px)', borderBottomWidth:'1px', borderBottomStyle:'solid', borderBottomColor:'rgba(255,255,255,0.1)', padding:'14px 24px', display:'flex', justifyContent:'space-between', alignItems:'center' }}>
        <div style={{ display:'flex', alignItems:'center', gap:'12px' }}>
          <img src={LOGO} alt="LS" style={{ height:'32px', objectFit:'contain', filter:'drop-shadow(0 0 10px rgba(0,210,255,0.5))' }} />
          <span style={{ fontWeight:800, fontSize:'14px', letterSpacing:'0.5px' }}>FleetOS</span>
        </div>
        <div style={{ display:'flex', gap:'10px' }}>
          <button onClick={onLogin} style={{ background:'rgba(255,255,255,0.1)', borderWidth:'1px', borderStyle:'solid', borderColor:'rgba(255,255,255,0.2)', color:'white', padding:'8px 16px', borderRadius:'20px', fontSize:'12px', cursor:'pointer', backdropFilter:'blur(10px)' }}>Login</button>
          <button onClick={onGetStarted} style={{ background:'white', color:'black', padding:'8px 16px', borderRadius:'20px', fontSize:'12px', fontWeight:700, border:'none', cursor:'pointer' }}>Get Started</button>
        </div>
      </nav>

      {/* MAIN CONTENT - Over Hero Background */}
      <div style={{ minHeight:'100vh', display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', padding:'80px 24px 40px', textAlign:'center', position:'relative', zIndex:2 }}>
        <div style={{ animation:'float 4s ease-in-out infinite' }}>
          <h1 style={{ fontSize:'clamp(40px, 7vw, 72px)', fontWeight:900, lineHeight:'0.95', letterSpacing:'-2px', textShadow:'0 0 40px rgba(0,210,255,0.5)' }}>Fleet Management<br /><span style={{ background:'linear-gradient(135deg, #00D2FF, #667eea, #764ba2)', WebkitBackgroundClip:'text', WebkitTextFillColor:'transparent', filter:'drop-shadow(0 0 20px rgba(0,210,255,0.3))' }}>Made Simple</span></h1>
        </div>
        
        <div style={{ display:'flex', gap:'16px', justifyContent:'center', marginTop:'36px', flexWrap:'wrap' }}>
          <button onClick={onGetStarted} style={{ background:'linear-gradient(135deg, #00D2FF, #667eea)', color:'white', padding:'18px 36px', borderRadius:'14px', border:'none', fontWeight:800, fontSize:'15px', cursor:'pointer', boxShadow:'0 0 30px rgba(0,210,255,0.5), 0 10px 20px rgba(0,0,0,0.3)', letterSpacing:'0.5px', transition:'all 0.3s' }}>Get Started →</button>
          <button onClick={onLogin} style={{ background:'rgba(255,255,255,0.08)', backdropFilter:'blur(16px)', borderWidth:'1px', borderStyle:'solid', borderColor:'rgba(255,255,255,0.15)', color:'white', padding:'18px 36px', borderRadius:'14px', cursor:'pointer', fontSize:'15px', fontWeight:600, boxShadow:'0 10px 20px rgba(0,0,0,0.2)' }}>Login</button>
        </div>

      </div>
      <style>{
        `@keyframes float {
          0%, 100% { transform: translateY(0px); }
          50% { transform: translateY(-8px); }
        }`
      }</style>
    </div>
  );
}




